import Foundation

/// Frequency-rank lookup for English words, backed by the asset generated by
/// scripts/generate-word-frequency.py (shared/pronunciation/word-frequency.txt).
///
/// The file is one lowercase word per line, ordered most→least frequent.
/// Lines starting with '#' are skipped (header comments).
///
/// Rank 1 = most frequent. Words absent from the list return `unknownRank`
/// (Int.max) so they sort to the end rather than being dropped.
///
/// Loaded lazily on first access via `shared`. A not-yet-loaded or
/// failed-to-load instance returns `unknownRank` for every query, so the
/// system degrades gracefully rather than breaking.
nonisolated final class WordFrequency: @unchecked Sendable {

    /// The process-wide singleton. Loads the bundled asset on first access.
    static let shared: WordFrequency = {
        let wf = WordFrequency()
        wf.loadBundled()
        return wf
    }()

    /// Sentinel rank returned for words not present in the frequency list.
    static let unknownRank = Int.max

    private let lock = NSLock()
    private var rankMap: [String: Int] = [:]

    var isLoaded: Bool {
        lock.lock(); defer { lock.unlock() }
        return !rankMap.isEmpty
    }

    /// Returns the frequency rank (1 = most common), or `unknownRank` if absent.
    func rank(of word: String) -> Int {
        lock.lock(); defer { lock.unlock() }
        return rankMap[word.lowercased()] ?? WordFrequency.unknownRank
    }

    /// Stably re-sorts `words` by frequency rank (common first).
    /// If the list is not loaded, returns `words` unchanged.
    func sortByFrequency(_ words: [String]) -> [String] {
        lock.lock()
        let map = rankMap
        lock.unlock()
        guard !map.isEmpty else { return words }
        // Attach stable index so that equal-rank entries preserve input order.
        return words
            .enumerated()
            .sorted { a, b in
                let ra = map[a.element.lowercased()] ?? WordFrequency.unknownRank
                let rb = map[b.element.lowercased()] ?? WordFrequency.unknownRank
                if ra != rb { return ra < rb }
                return a.offset < b.offset
            }
            .map(\.element)
    }

    // MARK: - Loading

    /// Initialise from a stream of lines (newline-separated).
    func load(lines: some Sequence<String>) {
        var map: [String: Int] = [:]
        map.reserveCapacity(32_768)
        var rank = 1
        for line in lines {
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }
            let word = trimmed.lowercased()
            if !word.isEmpty {
                map[word] = rank
                rank += 1
            }
        }
        lock.lock(); defer { lock.unlock() }
        rankMap = map
    }

    private func loadBundled() {
        let bundles = [Bundle.main, Bundle(for: WordFrequencyBundleMarker.self)]
        for bundle in bundles {
            guard let url = bundle.url(forResource: "word-frequency", withExtension: "txt"),
                  let text = try? String(contentsOf: url, encoding: .utf8) else {
                continue
            }
            load(lines: text.components(separatedBy: .newlines))
            return
        }
        // Asset missing: silently degrade — rankMap stays empty.
    }
}

private final class WordFrequencyBundleMarker: NSObject {}
